<script setup>
import { computed,onMounted,ref,watch } from 'vue'
import { useRoute,useRouter } from 'vue-router'
import { fetchSeoKeywordDetail } from '../../api/seo'
import { currentTenantId } from '../../store/session'
import { formatSeoRankTime } from './seoRankTime'
const route=useRoute(),router=useRouter(),loading=ref(false),error=ref(''),data=ref(null)
const engines=[{k:'baidu',n:'百度'},{k:'google',n:'Google'},{k:'bing',n:'Bing'},{k:'360',n:'360'},{k:'sogou',n:'搜狗'}]
const engineKeys=new Set(engines.map(item=>item.k))
const engine=computed(()=>engineKeys.has(String(route.query.engine))?String(route.query.engine):'baidu')
const device=computed(()=>route.query.device==='mobile'?'mobile':'desktop')
const region=computed(()=>String(route.query.region||'全国'))
const detail=computed(()=>data.value?.keyword||{}),history=computed(()=>data.value?.rank_history||[]),fmt=v=>v==null?'—':Number(v).toLocaleString('zh-CN')
const sourceLabels={manual_import:'人工导入',manual:'人工录入',chinaz_top50:'站长之家 Top50',dataforseo:'DataForSEO',dataforseo_live:'DataForSEO 实时排名',gsc:'Google Search Console'}
const deviceLabels={desktop:'PC',mobile:'移动端'}
const points=computed(()=>{const rows=history.value.filter(i=>i.rank!=null);if(!rows.length)return'';const max=Math.max(50,...rows.map(i=>i.rank));return rows.map((i,n)=>`${38+n*(706/Math.max(rows.length-1,1))},${16+(i.rank-1)/(max-1)*206}`).join(' ')})
const latest=computed(()=>history.value.filter(i=>i.rank!=null).at(-1)),previous=computed(()=>history.value.filter(i=>i.rank!=null).at(-2)),delta=computed(()=>latest.value&&previous.value?previous.value.rank-latest.value.rank:null)
const diagnoses=computed(()=>data.value?.diagnoses||[]),optimizationTask=computed(()=>data.value?.optimization_task||null)
async function load(){if(!currentTenantId.value){error.value='请先选择客户';return}loading.value=true;try{data.value=await fetchSeoKeywordDetail({keywordId:route.params.keywordId,tenantId:currentTenantId.value,engine:engine.value,device:device.value,region:region.value,days:90});error.value=''}catch(e){error.value=e.message}finally{loading.value=false}}
function setRankContext(nextEngine=engine.value,nextDevice=device.value){router.replace({query:{...route.query,engine:engineKeys.has(nextEngine)?nextEngine:'baidu',device:nextDevice==='mobile'?'mobile':'desktop'}})}
function openOptimizationTask(){if(optimizationTask.value){router.push({path:'/seo/content/editor',query:{id:optimizationTask.value.id,site_id:optimizationTask.value.site_id}});return}router.push({path:'/seo/content/articles',query:{keyword_id:detail.value.id}})}
watch([engine,device,region,currentTenantId,()=>route.params.keywordId],load);onMounted(load)
</script>
<template><div class="keyword-assets detail-prototype" v-loading="loading"><el-alert v-if="error" :title="error" type="warning" :closable="false"/><template v-if="data"><section class="kw-hero"><div><div class="kw-kicker">Keyword detail</div><h2>{{detail.keyword}}</h2><p>{{detail.cluster||'未归类'}} · {{detail.intent||'意图待判断'}} · 当前由“{{detail.landing_page||'未绑定页面'}}”承接。</p></div><div class="kw-actions"><button class="kw-btn" @click="router.push({path:'/seo/rankings',query:{engine,device}})">← 返回排名监控</button><button class="kw-btn primary" @click="openOptimizationTask">{{optimizationTask?'查看优化任务':'＋ 创建优化任务'}}</button></div></section><section class="kw-metrics"><article class="kw-metric" data-mark="R"><span>{{engines.find(i=>i.k===engine)?.n}} · {{deviceLabels[device]}} 当前排名</span><strong>{{detail.latest_rank||'100+'}}</strong><small :class="delta>0?'up':delta<0?'down':''">{{delta==null?'尚无周期对比':delta>0?`本周期提升 ${delta} 位`:delta<0?`本周期下降 ${Math.abs(delta)} 位`:'排名持平'}}</small></article><article class="kw-metric" data-mark="V"><span>月搜索量</span><strong>{{fmt(detail.monthly_volume)}}</strong><small>自然搜索需求规模</small></article><article class="kw-metric" data-mark="D"><span>竞争难度</span><strong>{{detail.difficulty==null?'—':`${detail.difficulty}/100`}}</strong><small>{{detail.difficulty>=70?'高竞争关键词':'中等竞争关键词'}}</small></article><article class="kw-metric" data-mark="P"><span>优化优先级</span><strong>{{detail.priority}}</strong><small>{{detail.status}}</small></article></section><div class="kw-grid-2"><section class="kw-card"><header class="kw-card-head"><div><h3>90 天排名曲线</h3><p>排名数字越小越好；数据来自真实排名快照</p></div><div class="rank-context"><div class="kw-segment"><button v-for="item in engines" :key="item.k" :class="{active:engine===item.k}" @click="setRankContext(item.k,device)">{{item.n}}</button></div><div class="kw-segment"><button :class="{active:device==='desktop'}" @click="setRankContext(engine,'desktop')">PC</button><button :class="{active:device==='mobile'}" @click="setRankContext(engine,'mobile')">移动端</button></div></div></header><div v-if="points" class="kw-chart"><svg viewBox="0 0 760 250" preserveAspectRatio="none"><line v-for="y in [16,67,119,170,222]" :key="y" class="gridline" x1="38" :y1="y" x2="744" :y2="y"/><polyline class="line" :points="points"/></svg></div><div v-else class="kw-empty"><b>暂无自然排名快照</b>从排名监控记录或导入排名数据</div></section><section class="kw-card"><header class="kw-card-head"><div><h3>关键词诊断</h3><p>基于排名、内容与承接页的行动建议</p></div></header><div class="kw-card-body"><div class="kw-alert-list"><div v-for="(item,index) in diagnoses" :key="item.title" class="kw-alert"><span class="mark">0{{index+1}}</span><div><h4>{{item.title}}</h4><p>{{item.detail}}</p></div><time>{{item.priority}}</time></div><div v-if="!diagnoses.length" class="kw-empty">当前没有需要处理的关键词诊断</div></div></div></section></div><section class="kw-card history"><header class="kw-card-head"><div><h3>历史排名记录</h3><p>仅显示当前所选搜索引擎和设备的真实排名快照</p></div></header><div class="kw-table-wrap"><table class="kw-table"><thead><tr><th>日期</th><th>自然排名</th><th>搜索引擎</th><th>设备/地区</th><th>排名 URL</th><th>数据来源</th></tr></thead><tbody><tr v-for="row in [...history].reverse()" :key="row.id"><td>{{formatSeoRankTime(row.checked_at)}}</td><td><b>#{{row.rank||'100+'}}</b></td><td><span class="kw-pill blue">{{engines.find(item=>item.k===row.engine)?.n||row.engine}}</span></td><td>{{deviceLabels[row.device]||row.device}} · {{row.region}}</td><td><div class="kw-link">{{row.result_url||'—'}}</div></td><td>{{sourceLabels[row.source]||row.source}}</td></tr><tr v-if="!history.length"><td colspan="6"><div class="kw-empty">当前引擎和设备暂无记录</div></td></tr></tbody></table></div></section></template></div></template>
<style>@import url('../../../public/deal-sniper-prototype/seo/assets/keyword-assets-v2.css');</style>
<style scoped>.detail-prototype{min-height:100%;padding:22px 26px 30px;background:#f5f7fb}.history{margin-top:15px}.rank-context{display:flex;flex-wrap:wrap;justify-content:flex-end;gap:8px}.kw-chart{padding:18px}.kw-chart svg{width:100%;height:250px}.gridline{stroke:#e9edf4}.line{fill:none;stroke:#2457d6;stroke-width:3}</style>
